local UIModule = CS.Engine.UI.UIModule

--- from: Assets/BundleResources/Prefabs/Gachapon/GachaponComTaskDialog.prefab > name: GachaponComTaskDialog
---@class GachaponComTaskDialog
---@field Env                           	GachaponComTaskDialog                   
---@field controller                    	Engine.UI.UILuaDialog                   
---@field TextTime2                     	UnityEngine.RectTransform               	@ 0    
---@field ImgBg                         	UnityEngine.RectTransform               	@ 1    
---@field FontStyleButtonGet            	UnityEngine.RectTransform               	@ 2    
---@field ListView                      	SuperScrollView.LoopListView2           	@ 3    
local GachaponComTaskDialog = Class("GachaponComTaskDialog")
local Cell = "GachaponComTaskCellNode"
local CellPath = "Game.Gachapon.GachaponComTaskCell"


function GachaponComTaskDialog:__init()

end

function GachaponComTaskDialog:__delete()
    self.controller = nil
end

function GachaponComTaskDialog:Awake()
    self:AddUIClick()
end

function GachaponComTaskDialog:AddUIClick()
    SetButtonAction(self.FontStyleButtonGet,Bind(self,self.OnOneKeyGetClick))
end

function GachaponComTaskDialog:OnFocus(focus)

end

function GachaponComTaskDialog:OnShow()

end

function GachaponComTaskDialog:OnInitialize()
    self.parameters = self.controller.Argument.parameters
    self.tasks = self.parameters.pool.feedbackTasks
    self:InitTaskView()
    self:RefreshTimeShow()
    self:FillBg()
end

function GachaponComTaskDialog:FillBg()
    if not string.isEmpty(self.parameters.pool.givingBackPicture) then
        CfUtils.FillImage(self.ImgBg, self.parameters.pool.givingBackPicture)
    end
end

function GachaponComTaskDialog:OnFinalize()

end

function GachaponComTaskDialog:RefreshTimeShow()
    local pool = self.parameters.pool
    if (pool:IsValidActivity() and checkInt(pool.activity.endRemainTime) <= 0) or (pool.remainSeconds == 0) then
        CfUtils.FillText(self.TextTime2, 0)
    else
        local remainTime = pool.activity.endRemainTime or pool.remainSeconds
        local day = tonumber(math.floor(remainTime/86400))
        local timer = ""
        if day > 0 then
            timer = localize("剩余_num_天", {_num_ = day})
        else
            timer = CfUtils.GetTimeHMS9(remainTime)
        end
        CfUtils.FillText(self.TextTime2, timer)
    end
end

function GachaponComTaskDialog:InitTaskView()
    self:SortTaskData()
    if self.ListView then
        local count = table.count(self.tasks)
        if not self.ListView.IsListViewInit then
            self.ListView:InitListView(count, Bind(self, self.OnRefreshCellIndex))
            self.ListView:UpdateDisplayItemCount(Cell)
        else
            GameUtils.ReloadData(self.ListView, count)
        end
    end
end

function GachaponComTaskDialog:SortTaskData()
    table.sort(self.tasks, function(a, b)
        if a.status == b.status then
            return a.id < b.id
        else
            if a.status == 1 then
                return true
            elseif a.status == 0 then
                return b.status ~= 1
            else
                return false
            end
        end
    end)
end

function GachaponComTaskDialog:OnRefreshCellIndex(listView, index)
    if index < 0 or index >= #self.tasks then
        return
    end

    local cell = listView:NewListViewItem(Cell)
    if not isNull(cell) then
        local tableCellEnv = CfUtils.GetLuaScr(cell, CellPath)
        if not isNull(tableCellEnv) then
            tableCellEnv:RefreshShow(self.tasks[index + 1],Bind(self,self.OnGetTaskRewardClick), index + 1)
            if listView.DisplayItemNumber < listView.DisplayItemCount then
                tableCellEnv:PlayDelayAnimByShow(listView.DisplayItemNumber)
                listView.DisplayItemNumber = listView.DisplayItemNumber + 1
            else
                tableCellEnv:PlayAnimByIdle()
            end
        end
    end
    return cell
end

function GachaponComTaskDialog:OnGetTaskRewardClick(id, index)
    local data = {
        poolId = self.parameters.pool.poolId,
        activityUuid = self.parameters.pool.activity.activityUuid,
        taskId = id
    }
    GameUtils.Request(Interfaces.GachaponDrawFeedBackTask, data,function(request,response)
        if checkNumber(response.errCode) == 0 then
            if self.tasks[index] then
                self.tasks[index].status = Constants.GetStatus.Has
            end
            local responseData = response.data
            if table.count(responseData.rewards) > 0 then
                GoodsUtils.DrawRewards(responseData.rewards)
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards } })
            end
            self:InitTaskView()
        end
    end)
end

function GachaponComTaskDialog:OnOneKeyGetClick()
    local isCanGet = self:IsCanGet()
    if not isCanGet then
        GameUtils.Toast(localize("没有可领取奖励"))
        return
    end

    local data = {
        poolId = self.parameters.pool.poolId,
        activityUuid = self.parameters.pool.activity.activityUuid,
    }
    GameUtils.Request(Interfaces.GachaponDrawFeedBackTask, data,function(request,response)
        if checkNumber(response.errCode) == 0 then
            self:UpdateAllTaskStatus()
            local responseData = response.data
            if table.count(responseData.rewards) > 0 then
                GoodsUtils.DrawRewards(responseData.rewards)
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards } })
            end
            self:InitTaskView()
        end
    end)
end

function GachaponComTaskDialog:UpdateAllTaskStatus()
    for i, v in pairs(self.tasks) do
        if v.status == Constants.GetStatus.Can then
            v.status = Constants.GetStatus.Has
        end
    end
end

function GachaponComTaskDialog:IsCanGet()
    for i, v in pairs(self.tasks) do
        if v.status == Constants.GetStatus.Can then
            return true
        end
    end
    return false
end

return GachaponComTaskDialog